<?php
require_once __DIR__ . '/../config/config.php'; require_once __DIR__ . '/../includes/functions.php';require_login();if(is_admin())redirect('admin/dashboard.php');
$st=$pdo->prepare("SELECT e.status,e.submitted_at,c.id course_id,c.title,c.price,c.is_free,c.slug,(SELECT COUNT(*) FROM lessons l WHERE l.course_id=c.id) lesson_count FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.submitted_at DESC");$st->execute([current_user()['id']]);$rows=$st->fetchAll();page_header('Student dashboard');?><h1>Welcome, <?=e(current_user()['full_name'])?></h1><p class="muted">Your courses and enrollment requests.</p><div class="grid"><?php foreach($rows as $r):?><article class="card"><h3><?=e($r['title'])?></h3><p><span class="badge <?=e($r['status'])?>"><?=e(ucfirst($r['status']))?></span></p><p><?= (int)$r['lesson_count']?> lessons</p><?php if($r['status']==='approved'):?><a class="btn" href="<?=e(BASE_URL)?>/student/learn.php?course_id=<?=(int)$r['course_id']?>">Open course</a><?php elseif($r['status']==='pending'):?><p>Your receipt is waiting for review by the administrator.</p><?php else:?><p>Your payment was not approved. You can submit a new receipt.</p><a class="btn" href="<?=e(BASE_URL)?>/student/submit-payment.php?course_id=<?=(int)$r['course_id']?>">Resubmit receipt</a><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><div class="card"><p>You have not enrolled in any course yet.</p><a class="btn" href="<?=e(BASE_URL)?>/index.php">Browse courses</a></div><?php endif;?></div><?php page_footer();?>
